import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to ensure owner behavior is general; use an address but we will only use the contract's owner
    // The deciding parameter is an arbitrary uint (unused) to satisfy fuzzing requirement and broaden search space.
    function testFuzz_property(uint256 fuzz) public {
        // property: after owner calls NETM(), balances(owner) == totalDistributed
        // set up: call NETM as the owner (contract constructor set owner = msg.sender at deployment)
        address owner = address(this); // in setUp we deployed c from this test contract
        // sanity: ensure we are the owner by calling transferOwnership then back to this if needed
        // but according to contract, owner was msg.sender at construction (this contract), so we are owner

        // call NETM as owner
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // Read totalDistributed and balance of owner via public getters
