        uint256 ownerBalance = c.balanceOf(owner);

        // The reference contract always sets balances[owner] = totalDistributed in NETM(), so call must succeed
        // and the equality must hold. Mutant omits the assignment so for some inputs the equality fails.
        assertTrue(ok && ownerBalance == totalDistributed);
    }
