pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller address who will attempt to call NETM
    function testFuzz_property(address caller) public {
        // keep caller wide but not zero address to ensure meaningful balances access
        vm.assume(caller != address(0));

        // Record balances of two addresses before the call: the original owner and the fuzzed caller
        address originalOwner = address(this); // not actual owner; need to read owner via storage? owner is not public. We cannot read owner directly; instead observe balances for caller and an unrelated address.
        // To capture the intended invariant we use: calling NETM by any non-owner should NOT change balances of an arbitrary target account `target` in the reference impl.

        // Choose a target address to observe; fuzzing ensures generality, but we keep it derived so both are not zero
        address target = address(uint160(uint256(keccak256(abi.encodePacked(caller, block.timestamp)))));

        uint256 balTargetBefore = c.balanceOf(target);
        uint256 balCallerBefore = c.balanceOf(caller);

        // The NETM function in contract C has signature NETM() and is public onlyOwner in reference.
        // Try to invoke NETM as the fuzzed caller. If caller is not the owner on reference, call will revert; we capture that and set ok flag.
        bool ok;
        // Use try/catch to observe whether NETM succeeded (mutant allows anyone so it may succeed; reference will only succeed if caller == owner)
        vm.prank(caller);
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call attempt, observe balances
        uint256 balTargetAfter = c.balanceOf(target);
        uint256 balCallerAfter = c.balanceOf(caller);

        // General rule (single assert): In the reference contract, if the NETM call did NOT succeed (ok == false), then balances of arbitrary addresses must be unchanged; 
        // the mutant allows NETM to succeed for non-owners and thus can change balances of caller or other addresses. We assert that when NETM reverted, target's balance remained unchanged.
        // This holds for all inputs on the reference (NETM reverts for non-owner and thus has no effect), but the mutant can make NETM succeed and change balances.
        if (!ok) {
            assertTrue(balTargetAfter == balTargetBefore);
        } else {
            // If the call succeeded, then it must have been made by the real owner in the reference implementation,
            // and in that case the reference also changes balances (owner gets totalDistributed). We still must assert something true for all inputs on reference;
            // when NETM succeeds in the reference it assigns totalDistributed to owner address (the caller). Hence after a successful call, the caller's balance must be at least previous caller balance.
            assertTrue(balCallerAfter >= balCallerBefore);
        }
    }
}

